import { Products } from "../Data/Products";
import { Product } from "./Product";
import "../styles/productContainer.css";

export const ProductsContainer = ({ itemQuantity, setItemQuantity }) => {
  return (
    <div className="ProductsContainer">
      {Products.map((product) => (
        // Se usa el código del producto como key en lugar de combinar título e índice
        <Product
          key={product.code} // Clave única basada en el código del producto
          srcImage={product.srcImage}
          title={product.title}
          code={product.code}
          price={product.price}
          itemQuantity={itemQuantity}
          setItemQuantity={setItemQuantity}
        />
      ))}
    </div>
  );
};
